import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import API from "../services/api";
import "./ProductoDetalle.css";

function ProductoDetalle(){

 const { id } = useParams();
 const navigate = useNavigate();

 const [producto,setProducto] = useState(null);

 useEffect(()=>{

  cargarProducto();

 },[]);


 const cargarProducto = async ()=>{

  try{

   const res = await API.get(`/productos/${id}`);

   setProducto(res.data);

  }catch(error){

   console.log("Error cargando producto");

  }

 };


 const agregarFavorito = ()=>{

  alert("Producto agregado a favoritos");

 };


 const contactarVendedor = ()=>{

  alert("Aquí abrirá el chat con el vendedor");

 };


 const comprarProducto = ()=>{

  alert("Proceso de compra");

 };


 if(!producto){

  return <h2 style={{textAlign:"center"}}>Cargando producto...</h2>;

 }


 return(

  <div className="detalle-container">

   <button
    className="btn-volver"
    onClick={()=>navigate(-1)}
   >
    ← Volver
   </button>


   <div className="detalle-grid">

    {/* IMAGEN */}

    <div className="detalle-imagen">

     <img
      src={`http://localhost:3000/uploads/${producto.imagen}`}
      alt={producto.tipo_producto}
     />

    </div>


    {/* INFORMACION */}

    <div className="detalle-info">

     <h2>{producto.tipo_producto}</h2>

     <p><b>Color:</b> {producto.color}</p>

     <p><b>Peso:</b> {producto.peso} ct</p>

     <p><b>Tratamiento:</b> {producto.tratamiento}</p>

     <p><b>Stock:</b> {producto.stock}</p>

     <p><b>Estado:</b> {producto.estado}</p>

     <p><b>Vendedor:</b> {producto.vendedor}</p>


     {/* PRECIO */}

     <div className="precio-box">

      <span>Precio</span>

      <h1>${producto.valor}</h1>

     </div>


     {/* BOTONES */}

     <div className="acciones">

      <button
       className="btn-comprar"
       onClick={comprarProducto}
      >
       Comprar
      </button>

      <button
       className="btn-favorito"
       onClick={agregarFavorito}
      >
       ⭐ Favorito
      </button>

      <button
       className="btn-contacto"
       onClick={contactarVendedor}
      >
       Contactar vendedor
      </button>

     </div>


     {/* CERTIFICADO */}

     <div className="certificado">

      <h3>Certificado</h3>

      <img
       src={`http://localhost:3000/uploads/${producto.certificado}`}
       alt="certificado"
       className="certificado-img"
      />

     </div>


     {/* SI ES JOYA */}

     {producto.tipo_producto === "joya" && (

      <div className="joya-box">

       <h3>Detalles de la Joya</h3>

       <p><b>Tiene Esmeralda:</b> {producto.tiene_esmeralda}</p>

       <p><b>Oro:</b> {producto.oro}</p>

       <p><b>Oro Rosado:</b> {producto.oro_rosado}</p>

       <p><b>Plata:</b> {producto.plata}</p>

      </div>

     )}

    </div>

   </div>

  </div>

 );

}

export default ProductoDetalle;
